313→    /// Create a new directory.
314→    pub fn handle_mkdir(
315→        fs: &mut CipherBoxFS,
316→        parent: u64,
317→        name: &OsStr,
318→        reply: ReplyEntry,
319→    ) {
320→        let name_str = match name.to_str() {
321→            Some(n) => n,
322→            None => {
323→                reply.error(libc::EINVAL);
324→                return;
325→            }
326→        };
327→
328→        if is_platform_special(name_str) {
329→            reply.error(libc::EACCES);
330→            return;
331→        }
332→
333→        let parent_exists = fs.inodes.get(parent).map(|inode| {
334→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
335→        });
336→        if parent_exists != Some(true) {
337→            reply.error(libc::ENOENT);
338→            return;
339→        }
340→
341→        log::debug!("mkdir: {} in parent {}", name_str, parent);
342→
343→        let result = (|| -> Result<fuser::FileAttr, String> {
344→            let folder_key = crate::crypto::utils::generate_file_key();
345→
346→            let (ipns_public_key, ipns_private_key) =
347→                crate::crypto::ed25519::generate_ed25519_keypair();
348→
349→            let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
350→                .map_err(|_| "Invalid IPNS public key length".to_string())?;
351→            let ipns_name = crate::crypto::ipns::derive_ipns_name(&ipns_pub_arr)
352→                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;
353→
354→            let wrapped_folder_key = crate::crypto::ecies::wrap_key(
355→                &folder_key, &fs.public_key,
356→            )
357→            .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
358→            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
359→
360→            let ino = fs.inodes.allocate_ino();
361→            let now = SystemTime::now();
362→
363→            let attr = FileAttrs {
364→                ino,
365→                size: 0,
366→                blocks: 0,
367→                atime: now,
368→                mtime: now,
369→                ctime: now,
370→                crtime: now,
371→                is_dir: true,
372→                perm: 0o755,
373→                nlink: 2,
374→            };
375→            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
376→
377→            let inode = InodeData {
378→                ino,
379→                parent_ino: parent,
380→                name: name_str.to_string(),
381→                kind: InodeKind::Folder {
382→                    ipns_name: ipns_name.clone(),
383→                    encrypted_folder_key: encrypted_folder_key_hex,
384→                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
385→                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
386→                    children_loaded: true,
387→                },
388→                attr,
389→                children: Some(vec![]),
390→                write_generation: 0,
391→            };
392→
393→            fs.inodes.insert(inode);
394→
395→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
396→                if let Some(ref mut children) = parent_inode.children {
397→                    children.push(ino);
398→                }
399→                parent_inode.attr.mtime = SystemTime::now();
400→                parent_inode.attr.ctime = SystemTime::now();
401→            }
402→
403→            let metadata = crate::crypto::folder::FolderMetadata {
404→                version: "v2".to_string(),
405→                children: vec![],
406→            };
407→
408→            let json_bytes = crate::fuse::encrypt_metadata_to_json(
409→                &metadata, &folder_key,
410→            )?;
411→
412→            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
413→                let wrapped = crate::crypto::ecies::wrap_key(&ipns_private_key, tee_key)
414→                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
415→                Some(hex::encode(&wrapped))
416→            } else {
417→                None
418→            };
419→            let tee_key_epoch = fs.tee_key_epoch;
420→
421→            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
422→                fs.build_folder_metadata(parent)?;
423→
424→            let api = fs.api.clone();
425→            let rt = fs.rt.clone();
426→            let ipns_name_clone = ipns_name.clone();
427→            let coordinator = fs.publish_coordinator.clone();
428→
429→            std::thread::spawn(move || {
430→                let result = rt.block_on(async {
431→                    let initial_cid = crate::api::ipfs::upload_content(
432→                        &api, &json_bytes,
433→                    ).await?;
434→
435→                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
436→                        .map_err(|_| "Invalid IPNS key length".to_string())?;
437→                    let value = format!("/ipfs/{}", initial_cid);
438→                    let record = crate::crypto::ipns::create_ipns_record(
439→                        &ipns_key_arr, &value, 0, 86_400_000,
440→                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
441→                    let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
442→                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;
443→
444→                    use base64::Engine;
445→                    let record_b64 = base64::engine::general_purpose::STANDARD
446→                        .encode(&marshaled);
447→
448→                    let req = crate::api::ipns::IpnsPublishRequest {
449→                        ipns_name: ipns_name_clone.clone(),
450→                        record: record_b64,
451→                        metadata_cid: initial_cid,
452→                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
453→                        key_epoch: tee_key_epoch,
454→                    };
455→                    crate::api::ipns::publish_ipns(&api, &req).await?;
456→
457→                    coordinator.record_publish(&ipns_name_clone, 0);
458→                    log::info!("New folder IPNS published: {}", ipns_name_clone);
459→
460→                    let lock = coordinator.get_lock(&parent_ipns_name);
461→                    let _guard = lock.lock().await;
462→
463→                    let parent_json = crate::fuse::encrypt_metadata_to_json(
464→                        &parent_metadata, &parent_folder_key,
465→                    )?;
466→
467→                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
468→
469→                    let parent_meta_cid = crate::api::ipfs::upload_content(
470→                        &api, &parent_json,
471→                    ).await?;
472→
473→                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
474→                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
475→                    let new_seq = seq + 1;
476→                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
477→                    let parent_record = crate::crypto::ipns::create_ipns_record(
478→                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
479→                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
480→                    let parent_marshaled = crate::crypto::ipns::marshal_ipns_record(
481→                        &parent_record,
482→                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
483→                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
484→                        .encode(&parent_marshaled);
485→
486→                    let parent_req = crate::api::ipns::IpnsPublishRequest {
487→                        ipns_name: parent_ipns_name.clone(),
488→                        record: parent_record_b64,
489→                        metadata_cid: parent_meta_cid,
490→                        encrypted_ipns_private_key: None,
491→                        key_epoch: None,
492→                    };
493→                    crate::api::ipns::publish_ipns(&api, &parent_req).await?;
494→
495→                    coordinator.record_publish(&parent_ipns_name, new_seq);
496→
497→                    if let Some(old) = parent_old_cid {
498→                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
499→                    }
500→
501→                    log::info!("Parent metadata published after mkdir");
502→                    Ok::<(), String>(())
503→                });
504→
505→                if let Err(e) = result {
506→                    log::error!("Background mkdir publish failed: {}", e);
507→                }
508→            });
509→
510→            Ok(fuse_attr)
511→        })();
512→
513→        match result {
514→            Ok(fuse_attr) => {
515→                reply.entry(&DIR_TTL, &fuse_attr, 0);
516→            }
517→            Err(e) => {
518→                log::error!("mkdir failed: {}", e);
519→                reply.error(libc::EIO);
520→            }
521→        }
522→    }
523→
524→    /// Remove an empty directory.
525→    pub fn handle_rmdir(
526→        fs: &mut CipherBoxFS,
527→        parent: u64,
528→        name: &OsStr,
529→        reply: ReplyEmpty,
530→    ) {
531→        let name_str = match name.to_str() {
532→            Some(n) => n,
533→            None => {
534→                reply.error(libc::ENOENT);
535→                return;
536→            }
537→        };
538→
539→        let child_ino = match fs.inodes.find_child(parent, name_str) {
540→            Some(ino) => ino,
541→            None => {
542→                reply.error(libc::ENOENT);
543→                return;
544→            }
545→        };
546→
547→        let cid_to_unpin = match fs.inodes.get(child_ino) {
548→            Some(inode) => {
549→                match &inode.kind {
550→                    InodeKind::Folder { ipns_name, .. } => {
551→                        if let Some(ref children) = inode.children {
552→                            if !children.is_empty() {
553→                                reply.error(libc::ENOTEMPTY);
554→                                return;
555→                            }
556→                        }
557→                        fs.metadata_cache.get(ipns_name)
558→                            .map(|cached| cached.cid.clone())
559→                    }
560→                    _ => {
561→                        reply.error(libc::ENOTDIR);
562→                        return;
563→                    }
564→                }
565→            }
566→            None => {
567→                reply.error(libc::ENOENT);
568→                return;
569→            }
570→        };
571→
572→        log::debug!("rmdir: {} from parent {}", name_str, parent);
573→
574→        fs.inodes.remove(child_ino);
575→
576→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
577→            parent_inode.attr.mtime = SystemTime::now();
578→            parent_inode.attr.ctime = SystemTime::now();
579→        }
580→
581→        if let Err(e) = fs.update_folder_metadata(parent) {
582→            log::error!("Failed to update folder metadata after rmdir: {}", e);
583→        }
584→
585→        if let Some(cid) = cid_to_unpin {
586→            let api = fs.api.clone();
587→            fs.rt.spawn(async move {
588→                if let Err(e) = crate::api::ipfs::unpin_content(&api, &cid).await {
589→                    log::debug!("Background unpin failed for {}: {}", cid, e);
590→                }
591→            });
592→        }
593→
594→        reply.ok();
595→    }
596→
597→    /// Rename or move a file/folder.
598→    pub fn handle_rename(
599→        fs: &mut CipherBoxFS,
600→        parent: u64,
601→        name: &OsStr,
602→        newparent: u64,
603→        newname: &OsStr,
604→        reply: ReplyEmpty,
605→    ) {
606→        log::debug!(
607→            "rename: {:?} (parent {}) -> {:?} (parent {})",
608→            name, parent, newname, newparent,
609→        );
610→        let name_str = match name.to_str() {
611→            Some(n) => n,
612→            None => {
613→                reply.error(libc::EINVAL);
614→                return;
615→            }
616→        };
617→        let newname_str = match newname.to_str() {
618→            Some(n) => n,
619→            None => {
620→                reply.error(libc::EINVAL);
621→                return;
622→            }
623→        };
624→
625→        // Find source inode (with FUSE-T truncated name fallback)
626→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
627→            Some(ino) => (ino, name_str.to_string()),
628→            None => {
629→                let parent_inode = match fs.inodes.get(parent) {
630→                    Some(i) => i,
631→                    None => {
632→                        reply.error(libc::ENOENT);
633→                        return;
634→                    }
635→                };
636→                let children = parent_inode.children.clone().unwrap_or_default();
637→                let mut matches: Vec<(u64, String)> = Vec::new();
638→                for &child_ino in &children {
639→                    if let Some(child) = fs.inodes.get(child_ino) {
640→                        if is_platform_special(&child.name) {
641→                            continue;
642→                        }
643→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
644→                            matches.push((child_ino, child.name.clone()));
645→                        }
646→                    }
647→                }
648→                if matches.len() == 1 {
649→                    log::debug!(
650→                        "rename suffix-match: truncated {:?} matched full name {:?}",
651→                        name_str, matches[0].1
652→                    );
653→                    (matches[0].0, matches[0].1.clone())
654→                } else {
655→                    log::debug!(
656→                        "rename failed: {:?} not found (suffix matches: {})",
657→                        name_str, matches.len()
658→                    );
659→                    reply.error(libc::ENOENT);
660→                    return;
661→                }
662→            }
663→        };
664→
665→        let name_str = &actual_name;
666→
667→        log::debug!(
668→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
669→            name_str, source_ino, parent, newname_str, newparent,
670→        );
671→
672→        // If destination exists, handle replacement
673→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
674→            // Self-replace (rename "a" to "a" in same dir): no-op
675→            if dest_ino == source_ino {
676→                reply.ok();
677→                return;
678→            }
679→
680→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
681→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
682→                let source_is_dir = fs.inodes.get(source_ino)
683→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
684→                    .unwrap_or(false);
685→                let dest_is_dir = matches!(
686→                    dest_inode.kind,
687→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
688→                );
689→                if source_is_dir && !dest_is_dir {
690→                    reply.error(libc::ENOTDIR);
691→                    return;
692→                }
693→                if !source_is_dir && dest_is_dir {
694→                    reply.error(libc::EISDIR);
695→                    return;
696→                }
697→
698→                match &dest_inode.kind {
699→                    InodeKind::Folder { .. } => {
700→                        if let Some(ref children) = dest_inode.children {
701→                            if !children.is_empty() {
702→                                reply.error(libc::ENOTEMPTY);
703→                                return;
704→                            }
705→                        }
706→                    }
707→                    InodeKind::File { cid, .. } => {
708→                        if !cid.is_empty() {
709→                            let cid_clone = cid.clone();
710→                            let api = fs.api.clone();
711→                            fs.rt.spawn(async move {
712→                                let _ = crate::api::ipfs::unpin_content(
713→                                    &api, &cid_clone,
714→                                ).await;
715→                            });
716→                        }
717→                    }
718→                    _ => {}
719→                }
720→            }
721→            fs.inodes.remove(dest_ino);
722→        }
723→
724→        // Remove source from old parent's name index (NFC-normalized)
725→        {
726→            use unicode_normalization::UnicodeNormalization;
727→            let nfc_key: String = name_str.nfc().collect();
728→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
729→        }
730→
731→        // Update the source inode's name and parent
732→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
733→            inode.name = newname_str.to_string();
734→            inode.parent_ino = newparent;
735→            inode.attr.ctime = SystemTime::now();
736→        }
737→
738→        // Update the name lookup index for the new location (NFC-normalized)
739→        {
740→            use unicode_normalization::UnicodeNormalization;
741→            let nfc_key: String = newname_str.nfc().collect();
742→            fs.inodes.name_to_ino.insert(
743→                (newparent, nfc_key),
744→                source_ino,
745→            );
746→        }
747→
748→        if parent != newparent {
749→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
750→                if let Some(ref mut children) = old_parent.children {
751→                    children.retain(|&c| c != source_ino);
752→                }
753→                old_parent.attr.mtime = SystemTime::now();
754→                old_parent.attr.ctime = SystemTime::now();
755→            }
756→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
757→                if let Some(ref mut children) = new_parent.children {
758→                    children.push(source_ino);
759→                }
760→                new_parent.attr.mtime = SystemTime::now();
761→                new_parent.attr.ctime = SystemTime::now();
762→            }
763→
764→            if let Err(e) = fs.update_folder_metadata(parent) {
765→                log::error!("Failed to update old parent metadata after rename: {}", e);
766→            }
767→            if let Err(e) = fs.update_folder_metadata(newparent) {
768→                log::error!("Failed to update new parent metadata after rename: {}", e);
769→            }
770→        } else {
771→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
772→                parent_inode.attr.mtime = SystemTime::now();
773→                parent_inode.attr.ctime = SystemTime::now();
774→            }
775→            if let Err(e) = fs.update_folder_metadata(parent) {
776→                log::error!("Failed to update parent metadata after rename: {}", e);
777→            }
778→        }
779→
780→        reply.ok();
781→    }
782→}
