 641→/**
 642→ * Replace file content in v2 metadata (content update).
 643→ *
 644→ * THIS IS THE PRIMARY BENEFIT OF PER-FILE IPNS: content updates publish
 645→ * ONLY the file's IPNS record. The folder metadata is NOT touched because
 646→ * the FilePointer still points to the same fileMetaIpnsName, which now
 647→ * resolves to the updated content.
 648→ *
 649→ * @param params.fileId - ID of file to update
 650→ * @param params.fileIpnsRecord - Updated file IPNS record from updateFileMetadata
 651→ * @param params.parentFolderState - Parent folder (used only to find the FilePointer)
 652→ * @returns Void -- no folder metadata update needed
 653→ * @throws Error if file not found
 654→ */
 655→export async function replaceFileInFolder(params: {
 656→  fileId: string;
 657→  fileIpnsRecord: FileIpnsRecordPayload;
 658→  parentFolderState: FolderNode;
 659→}): Promise<void> {
 660→  // 1. Verify file exists in parent's children
 661→  const fileExists = params.parentFolderState.children.some(
 662→    (c) => c.type === 'file' && c.id === params.fileId
 663→  );
 664→
 665→  if (!fileExists) throw new Error('File not found');
 666→
 667→  // 2. Publish ONLY the file IPNS record (folder metadata untouched!)
 668→  // This is the key optimization: content update does NOT modify folder metadata.
 669→  const publishResult = await batchPublishIpnsRecords([
 670→    { ...params.fileIpnsRecord, recordType: 'file' },
 671→  ]);
 672→
 673→  if (publishResult.totalFailed > 0) {
 674→    throw new Error('Failed to publish file IPNS record');
 675→  }
 676→}
 677→
 678→/**
 679→ * Calculate the maximum depth of a folder's subtree.
 680→ *
 681→ * Used to check if moving a folder would exceed the depth limit.
 682→ *
 683→ * @param folderId - Folder ID to calculate subtree depth for
 684→ * @param folders - Current folder tree
 685→ * @returns Maximum depth in the subtree (0 if folder has no children)
 686→ */
 687→export function calculateSubtreeDepth(
 688→  folderId: string,
 689→  folders: Record<string, FolderNode>
 690→): number {
 691→  const folder = folders[folderId];
 692→  if (!folder) return 0;
 693→
 694→  let maxChildDepth = 0;
 695→  for (const child of folder.children) {
 696→    if (child.type === 'folder') {
 697→      const childDepth = 1 + calculateSubtreeDepth(child.id, folders);
 698→      maxChildDepth = Math.max(maxChildDepth, childDepth);
 699→    }
 700→  }
 701→
 702→  return maxChildDepth;
 703→}
 704→
 705→/**
 706→ * Check if a folder is a descendant of a potential ancestor.
 707→ *
 708→ * Used to prevent moving a folder into itself or its descendants.
 709→ *
 710→ * @param folderId - Folder to check
 711→ * @param potentialAncestorId - Potential ancestor folder ID
 712→ * @param folders - Current folder tree
 713→ * @returns true if folderId is a descendant of potentialAncestorId
 714→ */
 715→export function isDescendantOf(
 716→  folderId: string,
 717→  potentialAncestorId: string,
 718→  folders: Record<string, FolderNode>
 719→): boolean {
 720→  let currentId: string | null = folderId;
 721→
 722→  while (currentId !== null) {
 723→    if (currentId === potentialAncestorId) return true;
 724→    const currentFolder: FolderNode | undefined = folders[currentId];
 725→    if (!currentFolder) break;
 726→    currentId = currentFolder.parentId;
 727→  }
 728→
 729→  return false;
 730→}
 731→
 732→/**
 733→ * Move a folder from one parent to another.
 734→ *
 735→ * Uses add-before-remove pattern to prevent data loss on failure.
 736→ * Validates depth limit and prevents moving folder into itself.
 737→ *
 738→ * @param params.folderId - ID of folder to move
 739→ * @param params.sourceFolderState - Current parent folder
 740→ * @param params.destFolderState - Destination parent folder
 741→ * @param params.folders - Full folder tree (for depth calculation)
 742→ * @throws Error if folder not found, name collision, depth limit exceeded,
 743→ *         or attempting to move folder into itself/descendant
 744→ */
 745→export async function moveFolder(params: {
 746→  folderId: string;
 747→  sourceFolderState: FolderNode;
 748→  destFolderState: FolderNode;
 749→  folders: Record<string, FolderNode>;
 750→}): Promise<void> {
 751→  // 1. Find folder in source
 752→  const folder = params.sourceFolderState.children.find(
 753→    (c) => c.type === 'folder' && c.id === params.folderId
 754→  ) as FolderEntry | undefined;
 755→
 756→  if (!folder) throw new Error('Folder not found');
 757→
 758→  // 2. Check name collision in destination
 759→  const nameExists = params.destFolderState.children.some((c) => c.name === folder.name);
 760→  if (nameExists) throw new Error('An item with this name already exists in destination');
 761→
 762→  // 3. Check depth limit (20 levels max)
 763→  const destDepth = getDepth(params.destFolderState.id, params.folders);
 764→  const folderSubtreeDepth = calculateSubtreeDepth(params.folderId, params.folders);
 765→  if (destDepth + 1 + folderSubtreeDepth > MAX_FOLDER_DEPTH) {
 766→    throw new Error(`Cannot move: would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`);
 767→  }
 768→
 769→  // 4. Prevent moving folder into itself or its descendants
 770→  if (isDescendantOf(params.destFolderState.id, params.folderId, params.folders)) {
 771→    throw new Error('Cannot move folder into itself or its subfolder');
 772→  }
 773→
 774→  // 5. ADD to destination FIRST (add-before-remove pattern)
 775→  const destChildren: FolderChild[] = [
 776→    ...params.destFolderState.children,
 777→    {
 778→      ...folder,
 779→      modifiedAt: Date.now(),
 780→    },
 781→  ];
 782→
 783→  await updateFolderMetadata({
 784→    folderId: params.destFolderState.id,
 785→    children: destChildren,
 786→    folderKey: params.destFolderState.folderKey,
 787→    ipnsPrivateKey: params.destFolderState.ipnsPrivateKey,
 788→    ipnsName: params.destFolderState.ipnsName,
 789→    sequenceNumber: params.destFolderState.sequenceNumber,
 790→  });
 791→
 792→  // 6. REMOVE from source AFTER destination confirmed
 793→  const sourceChildren = params.sourceFolderState.children.filter(
 794→    (c) => !(c.type === 'folder' && c.id === params.folderId)
 795→  );
 796→
 797→  await updateFolderMetadata({
 798→    folderId: params.sourceFolderState.id,
 799→    children: sourceChildren,
 800→    folderKey: params.sourceFolderState.folderKey,
 801→    ipnsPrivateKey: params.sourceFolderState.ipnsPrivateKey,
 802→    ipnsName: params.sourceFolderState.ipnsName,
 803→    sequenceNumber: params.sourceFolderState.sequenceNumber,
 804→  });
 805→}
 806→
 807→/**
 808→ * Move a file from one folder to another (v2).
 809→ *
 810→ * Uses add-before-remove pattern to prevent data loss on failure.
 811→ * FilePointer contains fileMetaIpnsName which stays the same across moves --
 812→ * no file IPNS record changes needed, only folder metadata changes.
 813→ *
 814→ * @param params.fileId - ID of file to move
 815→ * @param params.sourceFolderState - Current parent folder
 816→ * @param params.destFolderState - Destination folder
 817→ * @throws Error if file not found or name collision exists
 818→ */
 819→export async function moveFile(params: {
 820→  fileId: string;
 821→  sourceFolderState: FolderNode;
 822→  destFolderState: FolderNode;
 823→}): Promise<void> {
 824→  // 1. Find file in source (v2: FilePointer)
 825→  const file = params.sourceFolderState.children.find(
 826→    (c) => c.type === 'file' && c.id === params.fileId
 827→  ) as FilePointer | undefined;
 828→
 829→  if (!file) throw new Error('File not found');
 830→
 831→  // 2. Check name collision in destination
 832→  const nameExists = params.destFolderState.children.some((c) => c.name === file.name);
 833→  if (nameExists) throw new Error('An item with this name already exists in destination');
 834→
 835→  // 3. ADD to destination FIRST
 836→  const destChildren: FolderChild[] = [
 837→    ...params.destFolderState.children,
 838→    {
 839→      ...file,
 840→      modifiedAt: Date.now(),
 841→    },
 842→  ];
 843→
 844→  await updateFolderMetadata({
 845→    folderId: params.destFolderState.id,
 846→    children: destChildren,
 847→    folderKey: params.destFolderState.folderKey,
 848→    ipnsPrivateKey: params.destFolderState.ipnsPrivateKey,
 849→    ipnsName: params.destFolderState.ipnsName,
 850→    sequenceNumber: params.destFolderState.sequenceNumber,
 851→  });
 852→
 853→  // 4. REMOVE from source AFTER
 854→  const sourceChildren = params.sourceFolderState.children.filter(
 855→    (c) => !(c.type === 'file' && c.id === params.fileId)
 856→  );
 857→
 858→  await updateFolderMetadata({
 859→    folderId: params.sourceFolderState.id,
 860→    children: sourceChildren,
 861→    folderKey: params.sourceFolderState.folderKey,
 862→    ipnsPrivateKey: params.sourceFolderState.ipnsPrivateKey,
 863→    ipnsName: params.sourceFolderState.ipnsName,
 864→    sequenceNumber: params.sourceFolderState.sequenceNumber,
 865→  });
 866→}
