 868→/**
 869→ * Rename a file within its parent folder (v2).
 870→ *
 871→ * Updates the FilePointer's name in the parent's metadata and publishes
 872→ * an updated IPNS record for the parent folder.
 873→ * File rename does NOT touch the file's own IPNS record -- only folder metadata.
 874→ *
 875→ * @param params.fileId - ID of file to rename
 876→ * @param params.newName - New name for the file
 877→ * @param params.parentFolderState - Parent folder containing this file
 878→ * @throws Error if file not found or name collision exists
 879→ */
 880→export async function renameFile(params: {
 881→  fileId: string;
 882→  newName: string;
 883→  parentFolderState: FolderNode;
 884→}): Promise<void> {
 885→  const children = [...params.parentFolderState.children];
 886→  const fileIndex = children.findIndex((c) => c.type === 'file' && c.id === params.fileId);
 887→
 888→  if (fileIndex === -1) throw new Error('File not found');
 889→
 890→  // Check name collision
 891→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.fileId);
 892→  if (nameExists) throw new Error('An item with this name already exists');
 893→
 894→  const file = children[fileIndex] as FilePointer;
 895→  children[fileIndex] = {
 896→    ...file,
 897→    name: params.newName,
 898→    modifiedAt: Date.now(),
 899→  };
 900→
 901→  await updateFolderMetadata({
 902→    folderId: params.parentFolderState.id,
 903→    children,
 904→    folderKey: params.parentFolderState.folderKey,
 905→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 906→    ipnsName: params.parentFolderState.ipnsName,
 907→    sequenceNumber: params.parentFolderState.sequenceNumber,
 908→  });
 909→}
