  1→import { useState, useCallback } from 'react';
  2→import { useFolderStore } from '../stores/folder.store';
  3→import { useVaultStore } from '../stores/vault.store';
  4→import { useAuthStore } from '../stores/auth.store';
  5→import { useQuotaStore } from '../stores/quota.store';
  6→import { unpinFromIpfs } from '../lib/api/ipfs';
  7→import * as folderService from '../services/folder.service';
  8→import { reWrapForRecipients } from '../services/share.service';
  9→import {
 10→  createFileMetadata,
 11→  resolveFileMetadata,
 12→  updateFileMetadata,
 13→  shouldCreateVersion,
 14→  getFileIpnsPrivateKey,
 15→} from '../services/file-metadata.service';
 16→import type { FileIpnsRecordPayload } from '../services/file-metadata.service';
 17→import type { FolderChild, FilePointer } from '@cipherbox/crypto';
 18→import { unwrapKey, hexToBytes } from '@cipherbox/crypto';
 19→import { getRootFolderState } from './folder-helpers';
 20→import type { FolderOperationState } from './folder-helpers';
 21→
 22→/**
 23→ * React hook for file add/update operations.
 24→ *
 25→ * Returns loading/error state and operation callbacks.
 26→ */
 27→export function useFileOperations() {
 28→  const [state, setState] = useState<FolderOperationState>({
 29→    isLoading: false,
 30→    error: null,
 31→  });
 32→
 33→  /**
 34→   * Add a file to a folder after upload (v2).
 35→   *
 36→   * Creates per-file IPNS metadata, then registers FilePointer in folder.
 37→   *
 38→   * @param parentId - Parent folder ID ('root' or folder UUID)
 39→   * @param fileData - Uploaded file data from upload service
 40→   * @returns Created file pointer
 41→   */
 42→  const handleAddFile = useCallback(
 43→    async (
 44→      parentId: string,
 45→      fileData: {
 46→        cid: string;
 47→        wrappedKey: string;
 48→        iv: string;
 49→        originalName: string;
 50→        originalSize: number;
 51→        mimeType?: string;
 52→        encryptionMode?: 'GCM' | 'CTR';
 53→      }
 54→    ): Promise<FilePointer> => {
 55→      setState({ isLoading: true, error: null });
 56→      try {
 57→        const folders = useFolderStore.getState().folders;
 58→        const vault = useVaultStore.getState();
 59→        const auth = useAuthStore.getState();
 60→
 61→        if (!auth.vaultKeypair) {
 62→          throw new Error('No ECIES keypair available - please log in again');
 63→        }
 64→
 65→        // Get parent folder state
 66→        const parentFolder =
 67→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
 68→
 69→        if (!parentFolder) {
 70→          throw new Error('Parent folder not found or vault not initialized');
 71→        }
 72→
 73→        // 1. Generate fileId and create per-file IPNS metadata
 74→        const fileId = crypto.randomUUID();
 75→        const { ipnsRecord, ipnsPrivateKeyEncrypted } = await createFileMetadata({
 76→          fileId,
 77→          cid: fileData.cid,
 78→          fileKeyEncrypted: fileData.wrappedKey,
 79→          fileIv: fileData.iv,
 80→          size: fileData.originalSize,
 81→          mimeType: fileData.mimeType ?? 'application/octet-stream',
 82→          folderKey: parentFolder.folderKey,
 83→          userPublicKey: auth.vaultKeypair.publicKey,
 84→          encryptionMode: fileData.encryptionMode,
 85→        });
 86→
 87→        // 2. Register FilePointer in folder (batch publishes file + folder IPNS)
 88→        const { filePointer, newSequenceNumber } = await folderService.addFileToFolder({
 89→          parentFolderState: parentFolder,
 90→          fileId,
 91→          name: fileData.originalName,
 92→          fileIpnsRecord: ipnsRecord,
 93→          ipnsPrivateKeyEncrypted,
 94→        });
 95→
 96→        // 3. Update local state with new child and sequence number
 97→        const updatedChildren: FolderChild[] = [...parentFolder.children, filePointer];
 98→        const store = useFolderStore.getState();
 99→        store.updateFolderChildren(parentId, updatedChildren);
100→        store.updateFolderSequence(parentId, newSequenceNumber);
101→
102→        // 4. Post-upload: re-wrap file key for share recipients (fire-and-forget)
103→        // Unwrap the fileKey from the owner-wrapped key, then delegate to reWrapForRecipients
104→        (async () => {
105→          try {
106→            const authState = useAuthStore.getState();
107→            if (!authState.vaultKeypair) return;
108→            const fileKey = await unwrapKey(
109→              hexToBytes(fileData.wrappedKey),
110→              authState.vaultKeypair.privateKey
111→            );
112→            try {
113→              await reWrapForRecipients({
114→                folderIpnsName: parentFolder.ipnsName,
115→                folders: useFolderStore.getState().folders,
116→                currentFolderId: parentFolder.id,
117→                newItems: [{ keyType: 'file', itemId: fileId, plaintextKey: fileKey }],
118→              });
119→            } finally {
120→              fileKey.fill(0);
121→            }
122→          } catch (err) {
123→            console.warn('[share] Post-upload file re-wrapping failed:', err);
124→          }
125→        })();
126→
127→        setState({ isLoading: false, error: null });
128→        return filePointer;
129→      } catch (err) {
130→        const error = err instanceof Error ? err.message : 'Failed to add file';
131→        setState({ isLoading: false, error });
132→        throw err;
133→      }
134→    },
135→    []
136→  );
137→
138→  /**
139→   * Add multiple files to a folder after upload (v2 batch).
140→   *
141→   * Creates per-file IPNS metadata for each file, then registers all
142→   * FilePointers via a single batch IPNS publish.
143→   *
144→   * @param parentId - Parent folder ID ('root' or folder UUID)
145→   * @param filesData - Array of uploaded file data from upload service
146→   * @returns Created file pointers
147→   */
148→  const handleAddFiles = useCallback(
149→    async (
150→      parentId: string,
151→      filesData: Array<{
152→        cid: string;
153→        wrappedKey: string;
154→        iv: string;
155→        originalName: string;
156→        originalSize: number;
157→        mimeType?: string;
158→        encryptionMode?: 'GCM' | 'CTR';
159→      }>
160→    ): Promise<FilePointer[]> => {
161→      setState({ isLoading: true, error: null });
162→      try {
163→        const folders = useFolderStore.getState().folders;
164→        const vault = useVaultStore.getState();
165→        const auth = useAuthStore.getState();
166→
167→        if (!auth.vaultKeypair) {
168→          throw new Error('No ECIES keypair available - please log in again');
169→        }
170→
171→        // Get parent folder state
172→        const parentFolder =
173→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
174→
175→        if (!parentFolder) {
176→          throw new Error('Parent folder not found or vault not initialized');
177→        }
178→
179→        // 1. Create per-file IPNS metadata for each file
180→        const userPublicKey = auth.vaultKeypair.publicKey;
181→        const filesWithRecords = await Promise.all(
182→          filesData.map(async (f) => {
183→            const fileId = crypto.randomUUID();
184→            const { ipnsRecord, ipnsPrivateKeyEncrypted } = await createFileMetadata({
185→              fileId,
186→              cid: f.cid,
187→              fileKeyEncrypted: f.wrappedKey,
188→              fileIv: f.iv,
189→              size: f.originalSize,
190→              mimeType: f.mimeType ?? 'application/octet-stream',
191→              folderKey: parentFolder.folderKey,
192→              userPublicKey,
193→              encryptionMode: f.encryptionMode,
194→            });
195→            return {
196→              fileId,
197→              name: f.originalName,
198→              fileIpnsRecord: ipnsRecord,
199→              ipnsPrivateKeyEncrypted,
200→            };
201→          })
202→        );
203→
204→        // 2. Register FilePointers in folder (batch publishes all IPNS records)
205→        const { filePointers, newSequenceNumber } = await folderService.addFilesToFolder({
206→          parentFolderState: parentFolder,
207→          files: filesWithRecords,
208→        });
209→
210→        // 3. Update local state with new children and sequence number
211→        const store = useFolderStore.getState();
212→        store.updateFolderChildren(parentId, [...parentFolder.children, ...filePointers]);
213→        store.updateFolderSequence(parentId, newSequenceNumber);
214→
215→        // 4. Post-upload: re-wrap file keys for share recipients (fire-and-forget)
216→        (async () => {
217→          const newItems: Array<{
218→            keyType: 'file' | 'folder';
219→            itemId: string;
220→            plaintextKey: Uint8Array;
221→          }> = [];
222→          try {
223→            const authState = useAuthStore.getState();
224→            if (!authState.vaultKeypair) return;
225→            const privateKey = authState.vaultKeypair.privateKey;
226→            for (let i = 0; i < filesData.length; i++) {
227→              const fileKey = await unwrapKey(hexToBytes(filesData[i].wrappedKey), privateKey);
228→              newItems.push({
229→                keyType: 'file',
230→                itemId: filesWithRecords[i].fileId,
231→                plaintextKey: fileKey,
232→              });
233→            }
234→            await reWrapForRecipients({
235→              folderIpnsName: parentFolder.ipnsName,
236→              folders: useFolderStore.getState().folders,
237→              currentFolderId: parentFolder.id,
238→              newItems,
239→            });
240→          } catch (err) {
241→            console.warn('[share] Post-upload batch file re-wrapping failed:', err);
242→          } finally {
243→            for (const item of newItems) {
244→              item.plaintextKey.fill(0);
245→            }
246→          }
247→        })();
248→
249→        setState({ isLoading: false, error: null });
250→        return filePointers;
251→      } catch (err) {
252→        const error = err instanceof Error ? err.message : 'Failed to add files';
253→        setState({ isLoading: false, error });
254→        throw err;
255→      }
256→    },
257→    []
258→  );
259→
260→  /**
261→   * Update a file's content in-place (v2: re-encrypt, update file IPNS, folder untouched).
262→   *
263→   * Old CIDs are preserved as version history (VER-01). Only pruned versions
264→   * (excess beyond max 10) have their CIDs unpinned.
265→   *
266→   * @param parentId - Parent folder ID ('root' or folder UUID)
267→   * @param fileData - New file data after re-encryption
268→   * @returns Resolves when the update is complete
269→   */
270→  const handleUpdateFile = useCallback(
271→    async (
272→      parentId: string,
273→      fileData: {
274→        fileId: string;
275→        newCid: string;
276→        newFileKeyEncrypted: string;
277→        newFileIv: string;
278→        newSize: number;
279→        forceVersion?: boolean; // true for web re-upload, false/undefined for text editor
280→      }
281→    ): Promise<void> => {
282→      setState({ isLoading: true, error: null });
283→      try {
284→        const folders = useFolderStore.getState().folders;
285→        const vault = useVaultStore.getState();
286→        const auth = useAuthStore.getState();
287→
288→        if (!auth.vaultKeypair) {
289→          throw new Error('No ECIES keypair available - please log in again');
290→        }
291→
292→        // Get parent folder state
293→        const parentFolder =
294→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
295→
296→        if (!parentFolder) {
297→          throw new Error('Parent folder not found or vault not initialized');
298→        }
299→
300→        // 1. Find the FilePointer in parent's children
301→        const filePointer = parentFolder.children.find(
302→          (c) => c.type === 'file' && c.id === fileData.fileId
303→        ) as FilePointer | undefined;
304→
305→        if (!filePointer) {
306→          throw new Error('File not found in folder');
307→        }
308→
309→        // 2. Resolve current file metadata from IPNS
310→        const { metadata: currentMetadata } = await resolveFileMetadata(
311→          filePointer.fileMetaIpnsName,
312→          parentFolder.folderKey
313→        );
314→
315→        // 3. Decrypt the file IPNS private key from FilePointer (or HKDF fallback)
316→        const { privateKey: fileIpnsPrivateKey, migratedIpnsPrivateKeyEncrypted } =
317→          await getFileIpnsPrivateKey(
318→            filePointer,
319→            auth.vaultKeypair.privateKey,
320→            auth.vaultKeypair.publicKey
321→          );
322→
323→        // 4. Determine whether to create a version entry
324→        const createVersion = shouldCreateVersion(currentMetadata, fileData.forceVersion ?? false);
325→
326→        let ipnsRecord: FileIpnsRecordPayload;
327→        let prunedCids: string[];
328→        try {
329→          // 5. Update file metadata and publish new IPNS record
330→          ({ ipnsRecord, prunedCids } = await updateFileMetadata({
331→            fileIpnsPrivateKey,
332→            fileMetaIpnsName: filePointer.fileMetaIpnsName,
333→            folderKey: parentFolder.folderKey,
334→            currentMetadata,
335→            updates: {
336→              cid: fileData.newCid,
337→              fileKeyEncrypted: fileData.newFileKeyEncrypted,
338→              fileIv: fileData.newFileIv,
339→              size: fileData.newSize,
340→            },
341→            createVersion,
342→          }));
343→        } finally {
344→          fileIpnsPrivateKey.fill(0);
345→        }
346→
347→        // 6. Publish only the file IPNS record (folder metadata untouched!)
348→        await folderService.replaceFileInFolder({
349→          fileId: fileData.fileId,
350→          fileIpnsRecord: ipnsRecord,
351→          parentFolderState: parentFolder,
352→        });
353→
354→        // 7. Update local state -- touch modifiedAt and persist migrated IPNS key if applicable
355→        const updatedChildren = parentFolder.children.map((child) => {
356→          if (child.type === 'file' && child.id === fileData.fileId) {
357→            return {
358→              ...child,
359→              modifiedAt: Date.now(),
360→              ...(migratedIpnsPrivateKeyEncrypted
361→                ? { ipnsPrivateKeyEncrypted: migratedIpnsPrivateKeyEncrypted }
362→                : {}),
363→            };
364→          }
365→          return child;
366→        });
367→
368→        const store = useFolderStore.getState();
369→        store.updateFolderChildren(parentId, updatedChildren);
370→
371→        // 7b. Lazy migration: persist wrapped IPNS key to folder metadata on IPFS
372→        if (migratedIpnsPrivateKeyEncrypted) {
373→          folderService
374→            .updateFolderMetadata({
375→              folderId: parentFolder.id,
376→              children: updatedChildren,
377→              folderKey: parentFolder.folderKey,
378→              ipnsPrivateKey: parentFolder.ipnsPrivateKey,
379→              ipnsName: parentFolder.ipnsName,
380→              sequenceNumber: parentFolder.sequenceNumber,
381→            })
382→            .then(({ newSequenceNumber }) => {
383→              useFolderStore.getState().updateFolderSequence(parentId, newSequenceNumber);
384→            })
385→            .catch((err) => {
386→              console.warn('Lazy IPNS key migration: folder re-publish failed, will retry:', err);
387→            });
388→        }
389→
390→        // 8. Only unpin CIDs of pruned versions (excess beyond max 10)
391→        // Old CIDs stay pinned as version history (VER-01)
392→        for (const prunedCid of prunedCids) {
393→          unpinFromIpfs(prunedCid).catch(() => {});
394→        }
395→
396→        // Refresh quota
397→        useQuotaStore.getState().fetchQuota();
398→
399→        setState({ isLoading: false, error: null });
400→      } catch (err) {
401→        const error = err instanceof Error ? err.message : 'Failed to update file';
402→        setState({ isLoading: false, error });
403→        throw err;
404→      }
405→    },
406→    []
407→  );
408→
409→  return {
410→    ...state,
411→    addFile: handleAddFile,
412→    addFiles: handleAddFiles,
413→    updateFile: handleUpdateFile,
414→  };
415→}
