import { Page } from '@playwright/test';

/**
 * Conflict detection test helpers.
 *
 * Simulates concurrent device publishes by calling the API publish endpoint
 * directly to increment a folder's server-side sequence number, making the
 * web client's local sequence stale.
 */

/**
 * Bump the server-side sequence number for a folder IPNS record.
 *
 * This simulates another device publishing to the same folder by calling the
 * API publish endpoint without an expectedSequenceNumber (backward-compatible
 * unconditional publish). The server increments the sequence number, making
 * the web client's local sequence stale. The web client's next folder mutation
 * (which sends its now-stale expectedSequenceNumber) will receive a 409.
 *
 * NOTE: Uses a dummy base64 record string which generates a delegated routing
 * warning in API logs because the IPNS record is not cryptographically valid.
 * This is expected -- we only need the DB sequence bump, not a valid IPNS
 * record for DHT propagation. The API still increments the sequence number
 * and returns 201.
 *
 * @param params.page - Playwright page instance (for page.request API calls)
 * @param params.apiBaseUrl - API base URL (e.g., "http://localhost:3000")
 * @param params.accessToken - Bearer token for authenticated API calls
 * @param params.rootIpnsName - IPNS name of the root folder to bump
 * @returns The new server-side sequence number after the bump
 */
export async function bumpServerSequence(params: {
  page: Page;
  apiBaseUrl: string;
  accessToken: string;
  rootIpnsName: string;
}): Promise<{ newSequenceNumber: string }> {
  const { page, apiBaseUrl, accessToken, rootIpnsName } = params;

  // Step 1: Resolve the current CID from the root folder's IPNS record.
  // The API's DB-cached resolve is reliable and fast (no delegated routing).
  const resolveResponse = await page.request.get(
    `${apiBaseUrl}/ipns/resolve?ipnsName=${encodeURIComponent(rootIpnsName)}`,
    {
      headers: { Authorization: `Bearer ${accessToken}` },
    }
  );

  if (!resolveResponse.ok()) {
    const body = await resolveResponse.text();
    throw new Error(`Failed to resolve IPNS for sequence bump (${resolveResponse.status()}): ${body}`);
  }

  const resolved = await resolveResponse.json() as {
    success: boolean;
    cid: string;
    sequenceNumber: string;
  };

  if (!resolved.success || !resolved.cid) {
    throw new Error(
      `IPNS resolve returned success=false or missing CID. Is the vault initialized? Response: ${JSON.stringify(resolved)}`
    );
  }

  // Step 2: Publish with the same CID but NO expectedSequenceNumber.
  // Omitting expectedSequenceNumber uses the backward-compatible unconditional
  // publish path which always succeeds and increments the sequence by 1.
  //
  // The dummy base64 record string is intentionally invalid as an IPNS record.
  // The API will log a warning when trying to relay it to delegated-ipfs.dev,
  // but the DB sequence bump succeeds regardless.
  const dummyRecord = Buffer.from('conflict-test-dummy-record-not-a-valid-ipns-record').toString('base64');

  const publishResponse = await page.request.post(`${apiBaseUrl}/ipns/publish`, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    data: {
      ipnsName: rootIpnsName,
      record: dummyRecord,
      metadataCid: resolved.cid,
      // No expectedSequenceNumber -- unconditional publish to simulate another device
    },
  });

  if (!publishResponse.ok()) {
    const body = await publishResponse.text();
    throw new Error(`Failed to bump server sequence (${publishResponse.status()}): ${body}`);
  }

  const published = await publishResponse.json() as { sequenceNumber: string };

  return { newSequenceNumber: published.sequenceNumber };
}

# test-conflict-detection.ps1 -- Verify FUSE conflict detection and re-sync behavior (Windows).
#
# Usage: .\test-conflict-detection.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   Shared secret for test-login (default: e2e-test-secret-ci-only)
#
# These tests verify that when the server-side IPNS sequence number is bumped
# (simulating another device publishing), the desktop detects the 409 conflict,
# re-syncs, and retries -- resulting in all files/directories being accessible.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

$TestEmail = "dev-key@cipherbox.local"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== Conflict Detection Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host ""

# ---- Setup: Authenticate via test-login ----
Write-Host "--- Setup: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

$AccessToken = $null
try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body
    $AccessToken = $AuthResponse.accessToken
} catch {
    Write-Host "FATAL: Authentication failed ($_)"
}

if (-not $AccessToken) {
    Write-Host "FATAL: Cannot proceed without authentication."
    Write-Host ""
    Write-Host "=== Conflict Detection Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    exit 1
}
Write-Host "  Authenticated successfully"

$Headers = @{ Authorization = "Bearer $AccessToken" }

# ---- Setup: Get root IPNS name from vault ----
Write-Host "--- Setup: Get root IPNS name from vault ---"
$RootIpns = $null
try {
    $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault" -Headers $Headers
    $RootIpns = $VaultResponse.rootIpnsName
} catch {
    Write-Host "FATAL: Failed to retrieve vault ($_)"
}

if (-not $RootIpns) {
    Write-Host "FATAL: No rootIpnsName found in vault -- cannot test conflict detection without a published vault."
    Write-Host "       Ensure the desktop app has made at least one FUSE write before running this test."
    Write-Host ""
    Write-Host "=== Conflict Detection Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "=================================="
    exit 1
}
Write-Host "  Root IPNS: $RootIpns"
Write-Host ""

# ---- Helper: Invoke-BumpServerSequence ----
# Bumps the server-side sequence number for a given IPNS name by publishing
# without expectedSequenceNumber (backward-compatible unconditional publish).
# This simulates another device publishing to the same folder.
function Invoke-BumpServerSequence {
    param([string]$IpnsName)

    # 1. Resolve current CID for this IPNS name (for the metadataCid field)
    $CurrentCid = $null
    try {
        $ResolveResp = Invoke-RestMethod -Uri "$ApiUrl/ipns/resolve?ipnsName=$IpnsName" -Headers $Headers
        $CurrentCid = if ($ResolveResp.cid) { $ResolveResp.cid } else { $ResolveResp.value }
    } catch {
        Write-Host "  WARNING: Could not resolve CID for $IpnsName"
    }

    if (-not $CurrentCid) {
        Write-Host "  WARNING: Using placeholder CID for $IpnsName"
        $CurrentCid = "bafybeigdyrzt5sfp7udm7hu76uh7y26nf3efuylqabf3oclgtqy55fbzdi"
    }

    # 2. Publish with a dummy record and no expectedSequenceNumber.
    #    This unconditionally increments the server-side sequence number,
    #    making the desktop's cached sequence stale.
    $DummyRecord = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes("dummy-conflict-test-record"))

    $PublishBody = @{
        ipnsName    = $IpnsName
        record      = $DummyRecord
        metadataCid = $CurrentCid
    } | ConvertTo-Json

    try {
        $PublishResp = Invoke-RestMethod -Uri "$ApiUrl/ipns/publish" `
            -Method Post `
            -Headers $Headers `
            -ContentType "application/json" `
            -Body $PublishBody
        if ($PublishResp.success) {
            Write-Host "  Server sequence bumped to $($PublishResp.sequenceNumber) for $IpnsName"
        } else {
            Write-Host "  WARNING: Publish response did not indicate success"
        }
    } catch {
        Write-Host "  WARNING: Failed to bump server sequence ($_)"
    }
}

# ---- Test 1: Write file via FUSE, bump server seq, write another file -> both readable ----
Write-Host "--- Test 1: Write file, bump server sequence, write another file -> both readable ---"

# Step 1: Write first file and wait for FUSE debounce + publish
try {
    Set-Content -Path "$MountPoint\conflict-test-1.txt" -Value "file-before-bump" -NoNewline -ErrorAction Stop
    Write-Host "  Wrote conflict-test-1.txt, waiting 8s for FUSE publish..."
    Start-Sleep -Seconds 8
} catch {
    Write-Host "  WARNING: Failed to write conflict-test-1.txt ($_)"
}

# Step 2: Bump server sequence to make desktop's local sequence stale
Write-Host "  Bumping server sequence..."
Invoke-BumpServerSequence -IpnsName $RootIpns

# Step 3: Write second file -- the FUSE publish will get a 409, re-sync, and retry
try {
    Set-Content -Path "$MountPoint\conflict-test-2.txt" -Value "file-after-bump" -NoNewline -ErrorAction Stop
    Write-Host "  Wrote conflict-test-2.txt, waiting 15s for conflict resolution + retry..."
    Start-Sleep -Seconds 15
} catch {
    Write-Host "  WARNING: Failed to write conflict-test-2.txt ($_)"
}

# Step 4: Verify both files are readable
$Content1 = $null
$Content2 = $null
try { $Content1 = (Get-Content -Path "$MountPoint\conflict-test-1.txt" -Raw -ErrorAction Stop).Trim() } catch {}
try { $Content2 = (Get-Content -Path "$MountPoint\conflict-test-2.txt" -Raw -ErrorAction Stop).Trim() } catch {}

if ($Content1 -eq "file-before-bump" -and $Content2 -eq "file-after-bump") {
    Test-Pass "Write file conflict: both files readable after re-sync and retry"
} elseif ($Content1 -ne "file-before-bump") {
    Test-Fail "Write file conflict: conflict-test-1.txt has unexpected content (got: '$Content1')"
} else {
    Test-Fail "Write file conflict: conflict-test-2.txt has unexpected content (got: '$Content2')"
}

# ---- Test 2: Create directory via FUSE, bump server seq, create file in dir -> both accessible ----
Write-Host "--- Test 2: Create directory, bump server sequence, create file in dir -> both accessible ---"

# Step 1: Create directory and wait for FUSE publish
try {
    New-Item -ItemType Directory -Path "$MountPoint\conflict-dir" -Force -ErrorAction Stop | Out-Null
    Write-Host "  Created conflict-dir, waiting 8s for FUSE publish..."
    Start-Sleep -Seconds 8
} catch {
    Write-Host "  WARNING: Failed to create conflict-dir ($_)"
}

# Step 2: Bump server sequence
Write-Host "  Bumping server sequence..."
Invoke-BumpServerSequence -IpnsName $RootIpns

# Step 3: Write file in directory -- the mkdir publish will hit 409, re-sync, retry
try {
    Set-Content -Path "$MountPoint\conflict-dir\nested.txt" -Value "nested-conflict-file" -NoNewline -ErrorAction Stop
    Write-Host "  Writing conflict-dir\nested.txt, waiting 15s for conflict resolution + retry..."
    Start-Sleep -Seconds 15
} catch {
    Write-Host "  WARNING: Failed to write conflict-dir\nested.txt ($_)"
}

# Step 4: Verify directory exists and file is readable
$DirExists = Test-Path "$MountPoint\conflict-dir" -PathType Container
$Nested = $null
try { $Nested = (Get-Content -Path "$MountPoint\conflict-dir\nested.txt" -Raw -ErrorAction Stop).Trim() } catch {}

if ($DirExists -and $Nested -eq "nested-conflict-file") {
    Test-Pass "Directory conflict: dir exists and nested file readable after re-sync and retry"
} elseif (-not $DirExists) {
    Test-Fail "Directory conflict: conflict-dir does not exist after re-sync"
} else {
    Test-Fail "Directory conflict: nested.txt has unexpected content (got: '$Nested')"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
Remove-Item -Path "$MountPoint\conflict-test-1.txt" -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$MountPoint\conflict-test-2.txt" -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$MountPoint\conflict-dir" -Recurse -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 3

# ---- Summary ----
Write-Host ""
Write-Host "=== Conflict Detection Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "=================================="

exit $Fail

import { test, expect, Browser, BrowserContext, Page } from '@playwright/test';
import {
  loginViaEmail,
  loginViaTestEndpoint,
  TEST_CREDENTIALS,
  type TestAuthState,
} from '../utils/web3auth-helpers';
import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
import { bumpServerSequence } from '../utils/conflict-helpers';
import { FileListPage } from '../page-objects/file-browser/file-list.page';
import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
import { ConfirmDialogPage } from '../page-objects/dialogs/confirm-dialog.page';
import { TextEditorDialogPage } from '../page-objects/dialogs/text-editor-dialog.page';

/**
 * Conflict Detection E2E Test Suite
 *
 * Verifies the full conflict detection flow end-to-end:
 * 1. Server-side sequence is bumped (simulating another device publishing)
 * 2. Web client detects 409 on its next folder publish
 * 3. Client re-syncs (fetches latest remote state)
 * 4. Client retries the operation with the fresh sequence
 * 5. User's operation succeeds and the item appears in the file list
 *
 * Tests cover:
 * - Upload file with stale folder sequence -> auto re-sync -> file visible
 * - Create folder with stale parent sequence -> auto re-sync -> folder visible
 * - Per-file IPNS publish (content update) does NOT trigger conflict detection
 *
 * Depends on:
 * - Plan 16-01: API accepts expectedSequenceNumber, returns 409 on mismatch
 * - Plan 16-02: Web client sends expectedSequenceNumber and handles 409 with re-sync + retry
 */
test.describe.serial('Conflict Detection', () => {
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;

  // Page objects (initialized after login)
  let fileList: FileListPage;
  let uploadZone: UploadZonePage;
  let createFolderDialog: CreateFolderDialogPage;
  let contextMenu: ContextMenuPage;
  let confirmDialog: ConfirmDialogPage;
  let textEditorDialog: TextEditorDialogPage;

  // Auth state -- used for direct API calls in bumpServerSequence
  let authState: TestAuthState | null = null;

  const apiBaseUrl = process.env.API_BASE_URL || 'http://localhost:3000';

  // Unique suffix per test run to avoid naming collisions
  const runId = Date.now().toString();

  // Cleanup: track items created during tests for deletion
  const createdItems: Array<{ name: string; type: 'file' | 'folder' }> = [];

  test.beforeAll(async ({ browser: testBrowser }) => {
    browser = testBrowser;
    context = await browser.newContext();
    page = await context.newPage();

    // Initialize page objects
    fileList = new FileListPage(page);
    uploadZone = new UploadZonePage(page);
    createFolderDialog = new CreateFolderDialogPage(page);
    contextMenu = new ContextMenuPage(page);
    confirmDialog = new ConfirmDialogPage(page);
    textEditorDialog = new TextEditorDialogPage(page);

    // Login using test-login endpoint (bypasses Core Kit, decouples from Web3Auth)
    if (process.env.TEST_LOGIN_SECRET) {
      authState = await loginViaTestEndpoint(page, TEST_CREDENTIALS.email);
    } else {
      await loginViaEmail(page, TEST_CREDENTIALS.email);
      // When using real Core Kit login, extract auth state from Zustand stores
      // for use in bumpServerSequence API calls
      authState = await page.evaluate(() => {
        const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
          auth: { getState: () => { accessToken: string } };
          vault: { getState: () => { rootIpnsName: string } };
        } | undefined;

        if (!stores) return null;

        const authStoreState = stores.auth.getState();
        const vaultStoreState = stores.vault.getState();

        return {
          accessToken: authStoreState.accessToken,
          rootIpnsName: vaultStoreState.rootIpnsName,
          // Non-sensitive fields only -- private keys stay in browser memory
          email: '',
          publicKeyHex: '',
          publicKeyArr: [],
          privateKeyArr: [],
          rootFolderKeyArr: [],
          rootIpnsPublicKeyArr: [],
          rootIpnsPrivateKeyArr: [],
          vaultId: '',
        } as TestAuthState;
      });
    }

    // Verify we're on the files page and the vault is accessible
    await page.waitForURL('**/files', { timeout: 60000 });
    await fileList.fileListContainer().waitFor({ state: 'visible', timeout: 30000 });
  });

  test.afterAll(async () => {
    cleanupTestFiles();
    if (context) {
      await context.close();
    }
  });

  // ============================================================
  // Helper: Get current access token from Zustand auth store
  // ============================================================

  /**
   * Get a fresh access token from the browser's Zustand auth store.
   * The token may be refreshed between tests.
   */
  async function getAccessToken(): Promise<string> {
    if (authState?.accessToken) {
      return authState.accessToken;
    }
    // Fallback: read from store if authState not available
    return await page.evaluate(() => {
      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
        auth: { getState: () => { accessToken: string } };
      };
      return stores?.auth?.getState()?.accessToken ?? '';
    });
  }

  /**
   * Get the root IPNS name from the browser's Zustand vault store.
   */
  async function getRootIpnsName(): Promise<string> {
    if (authState?.rootIpnsName) {
      return authState.rootIpnsName;
    }
    return await page.evaluate(() => {
      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
        vault: { getState: () => { rootIpnsName: string } };
      };
      return stores?.vault?.getState()?.rootIpnsName ?? '';
    });
  }

  // ============================================================
  // Test 1: Upload file with stale sequence -> conflict -> retry
  // ============================================================

  test('upload file to root when sequence is stale -> conflict auto-resolved -> file appears', async () => {
    test.slow(); // Allow extra time for conflict re-sync cycle

    const fileName = `conflict-upload-${runId}.txt`;

    // Step 1: Bump the server-side sequence number so the client's local
    // sequence becomes stale. This simulates another device publishing.
    const accessToken = await getAccessToken();
    const rootIpnsName = await getRootIpnsName();

    expect(accessToken).toBeTruthy();
    expect(rootIpnsName).toBeTruthy();

    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });

    // Step 2: Upload a test file via the upload zone.
    // The client will:
    // - Encrypt the file content and upload to IPFS
    // - Build the new folder metadata (with the new file added)
    // - Publish the folder IPNS record with its (now-stale) expectedSequenceNumber
    // - Receive a 409 Conflict response from the API
    // - Re-sync: fetch the latest folder metadata from IPNS
    // - Retry the upload with the fresh sequence number
    // - Succeed on retry
    const testFile = createTestTextFile(fileName, `Conflict detection test file - ${runId}`);
    await uploadZone.uploadFile(testFile.path);

    // Step 3: Assert the file appears in the file list despite the initial
    // conflict. Use a generous timeout to allow for the re-sync cycle.
    await fileList.waitForItemToAppear(fileName, { timeout: 60000 });

    // Step 4: Assert the operation completed successfully (no persistent error).
    // The upload zone should not show an error after conflict auto-resolution.
    const hasUploadError = await uploadZone.hasError();
    expect(hasUploadError).toBe(false);

    // Track for cleanup
    createdItems.push({ name: fileName, type: 'file' });
  });

  // ============================================================
  // Test 2: Create folder with stale sequence -> conflict -> retry
  // ============================================================

  test('create folder when parent sequence is stale -> conflict auto-resolved -> folder appears', async () => {
    test.slow(); // Allow extra time for conflict re-sync cycle

    const folderName = `conflict-folder-${runId}`;

    // Step 1: Bump the server-side sequence number again.
    const accessToken = await getAccessToken();
    const rootIpnsName = await getRootIpnsName();

    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });

    // Step 2: Create a folder via the new-folder button.
    // The client will hit the same 409 -> re-sync -> retry flow.
    const newFolderButton = page.locator('.file-browser-new-folder-button');
    await newFolderButton.click();
    await createFolderDialog.waitForOpen();
    await createFolderDialog.createFolder(folderName);

    // Step 3: Assert the folder appears in the file list.
    await fileList.waitForItemToAppear(folderName, { timeout: 60000 });

    // Step 4: Verify no persistent error state after conflict auto-resolution.
    const folderVisible = await fileList.isItemVisible(folderName);
    expect(folderVisible).toBe(true);

    // Track for cleanup
    createdItems.push({ name: folderName, type: 'folder' });
  });

  // ============================================================
  // Test 3 (negative): Per-file IPNS publish does NOT conflict
  // ============================================================

  test('per-file IPNS content update does not trigger conflict even with stale folder sequence', async () => {
    test.slow(); // Allow for file edit + save cycle

    // Step 1: Upload a text file to edit later.
    // This resets/syncs the root folder sequence as a side effect of the
    // successful publish from Test 2.
    const editFileName = `conflict-edit-target-${runId}.txt`;
    const originalContent = `Original content for conflict edit test - ${runId}`;
    const updatedContent = `Updated content via text editor - ${runId} - modified`;

    const testFile = createTestTextFile(editFileName, originalContent);
    await uploadZone.uploadFile(testFile.path);
    await fileList.waitForItemToAppear(editFileName, { timeout: 30000 });

    // Step 2: Bump the folder's server-side sequence number.
    // This makes the client's local folder sequence stale.
    const accessToken = await getAccessToken();
    const rootIpnsName = await getRootIpnsName();

    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });

    // Step 3: Open the text editor for the file and save new content.
    // The text editor save flow calls handleUpdateFile, which publishes only
    // the per-file IPNS record (NOT the folder IPNS record). Per the Phase 16
    // design, per-file IPNS publishes use last-write-wins with no
    // expectedSequenceNumber, so they never trigger conflict detection.
    await fileList.rightClickItem(editFileName);
    await contextMenu.waitForOpen();
    await contextMenu.clickEdit();

    await textEditorDialog.waitForOpen({ timeout: 15000 });
    await textEditorDialog.clearAndType(updatedContent);
    await textEditorDialog.clickSave();
    await textEditorDialog.waitForClose({ timeout: 30000 });

    // Step 4: Assert the file update completed without a persistent error.
    // The file should still be visible in the list (not removed by an error).
    await fileList.waitForItemToAppear(editFileName, { timeout: 15000 });
    const fileVisible = await fileList.isItemVisible(editFileName);
    expect(fileVisible).toBe(true);

    // Step 5: Verify no upload-zone error state.
    const hasUploadError = await uploadZone.hasError();
    expect(hasUploadError).toBe(false);

    // Track for cleanup
    createdItems.push({ name: editFileName, type: 'file' });
  });

  // ============================================================
  // Cleanup: Remove all items created during conflict tests
  // ============================================================

  test('cleanup: delete conflict test items', async () => {
    // Delete items in reverse creation order (files first, then folders)
    const itemsToDelete = [...createdItems].reverse();

    for (const item of itemsToDelete) {
      const isVisible = await fileList.isItemVisible(item.name).catch(() => false);
      if (!isVisible) continue;

      await fileList.rightClickItem(item.name);
      await contextMenu.waitForOpen();
      await contextMenu.clickDelete();
      await confirmDialog.waitForOpen();
      await confirmDialog.clickConfirm();
      await fileList.waitForItemToDisappear(item.name, { timeout: 30000 });
    }
  });
});

