105→
106→    if resp.status().as_u16() == 409 {
107→        // Parse conflict response body: { currentSequenceNumber: "..." }
108→        let body: serde_json::Value = resp.json().await.unwrap_or_default();
109→        let current_seq = body["currentSequenceNumber"]
110→            .as_str()
111→            .unwrap_or("0")
112→            .to_string();
113→        return Ok(PublishResult::Conflict {
114→            current_sequence_number: current_seq,
