230→/// Merge local children onto remote children to resolve a concurrent-edit conflict.
231→///
232→/// Strategy (last-writer-wins per child, additive merge):
233→/// - Start with remote children as base
234→/// - For each child also present locally (by IPNS name): use local version (handles rename)
235→/// - For each child present locally but NOT in remote: add it (new file/folder from this device)
236→/// - For each child present in remote but NOT locally: keep remote version UNLESS local had the
237→///   child at all (i.e., we explicitly deleted it). If local children array was empty (no children
238→///   at all), keep remote to be safe.
239→///
240→/// This is the correct merge behavior that preserves all devices' changes.
241→#[cfg(any(feature = "fuse", feature = "winfsp"))]
242→fn merge_folder_children(
243→    local: &crate::crypto::folder::FolderMetadata,
244→    remote: crate::crypto::folder::FolderMetadata,
245→) -> crate::crypto::folder::FolderMetadata {
246→    use crate::crypto::folder::FolderChild;
247→
248→    /// Extract the stable IPNS identifier for a child entry.
249→    fn child_ipns_key(child: &FolderChild) -> &str {
250→        match child {
251→            FolderChild::Folder(f) => f.ipns_name.as_str(),
252→            FolderChild::File(f) => f.file_meta_ipns_name.as_str(),
253→        }
254→    }
255→
256→    // Build lookup maps keyed by IPNS name.
257→    let local_by_ipns: std::collections::HashMap<String, &FolderChild> = local
258→        .children
259→        .iter()
260→        .map(|c| (child_ipns_key(c).to_string(), c))
261→        .collect();
262→
263→    let remote_by_ipns: std::collections::HashMap<String, FolderChild> = remote
264→        .children
265→        .into_iter()
266→        .map(|c| (child_ipns_key(&c).to_string(), c))
267→        .collect();
268→
269→    let mut merged: Vec<FolderChild> = Vec::new();
270→
271→    // Walk remote children: keep local version if it exists (handles rename/modify),
272→    // drop if local explicitly deleted it (child absent from local AND local had entries).
273→    for (ipns, remote_child) in &remote_by_ipns {
274→        if let Some(local_child) = local_by_ipns.get(ipns) {
275→            // Both devices have this child -- use local version (handles rename)
276→            merged.push((*local_child).clone());
277→        } else if local.children.is_empty() {
278→            // Local metadata has no children at all -- unexpected edge case, preserve remote
279→            merged.push(remote_child.clone());
280→        } else {
281→            // Child exists in remote but not local -- this was an explicit local delete.
282→            // Drop it (do not include in merged result).
283→        }
284→    }
285→
286→    // Add any locally-added children that don't exist in remote (new files/folders).
287→    for (ipns, local_child) in &local_by_ipns {
288→        if !remote_by_ipns.contains_key(ipns) {
289→            merged.push((*local_child).clone());
290→        }
291→    }
292→
293→    crate::crypto::folder::FolderMetadata {
294→        version: "v2".to_string(),
295→        children: merged,
296→    }
297→}
