  1→import { test, expect, Browser, BrowserContext, Page } from '@playwright/test';
  2→import {
  3→  loginViaEmail,
  4→  loginViaTestEndpoint,
  5→  TEST_CREDENTIALS,
  6→  type TestAuthState,
  7→} from '../utils/web3auth-helpers';
  8→import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
  9→import { bumpServerSequence } from '../utils/conflict-helpers';
 10→import { FileListPage } from '../page-objects/file-browser/file-list.page';
 11→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
 12→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
 13→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
 14→import { ConfirmDialogPage } from '../page-objects/dialogs/confirm-dialog.page';
 15→import { TextEditorDialogPage } from '../page-objects/dialogs/text-editor-dialog.page';
 16→
 17→/**
 18→ * Conflict Detection E2E Test Suite
 19→ *
 20→ * Verifies the full conflict detection flow end-to-end:
 21→ * 1. Server-side sequence is bumped (simulating another device publishing)
 22→ * 2. Web client detects 409 on its next folder publish
 23→ * 3. Client re-syncs (fetches latest remote state)
 24→ * 4. Client retries the operation with the fresh sequence
 25→ * 5. User's operation succeeds and the item appears in the file list
