 27→ * Tests cover:
 28→ * - Upload file with stale folder sequence -> auto re-sync -> file visible
 29→ * - Create folder with stale parent sequence -> auto re-sync -> folder visible
 30→ * - Per-file IPNS publish (content update) does NOT trigger conflict detection
 31→ *
 32→ * Depends on:
 33→ * - Plan 16-01: API accepts expectedSequenceNumber, returns 409 on mismatch
 34→ * - Plan 16-02: Web client sends expectedSequenceNumber and handles 409 with re-sync + retry
 35→ */
 36→test.describe.serial('Conflict Detection', () => {
 37→  let browser: Browser;
 38→  let context: BrowserContext;
 39→  let page: Page;
 40→
 41→  // Page objects (initialized after login)
 42→  let fileList: FileListPage;
 43→  let uploadZone: UploadZonePage;
 44→  let createFolderDialog: CreateFolderDialogPage;
 45→  let contextMenu: ContextMenuPage;
 46→  let confirmDialog: ConfirmDialogPage;
 47→  let textEditorDialog: TextEditorDialogPage;
 48→
 49→  // Auth state -- used for direct API calls in bumpServerSequence
 50→  let authState: TestAuthState | null = null;
 51→
 52→  const apiBaseUrl = process.env.API_BASE_URL || 'http://localhost:3000';
 53→
 54→  // Unique suffix per test run to avoid naming collisions
 55→  const runId = Date.now().toString();
 56→
 57→  // Cleanup: track items created during tests for deletion
 58→  const createdItems: Array<{ name: string; type: 'file' | 'folder' }> = [];
 59→
 60→  test.beforeAll(async ({ browser: testBrowser }) => {
 61→    browser = testBrowser;
 62→    context = await browser.newContext();
 63→    page = await context.newPage();
 64→
 65→    // Initialize page objects
 66→    fileList = new FileListPage(page);
 67→    uploadZone = new UploadZonePage(page);
 68→    createFolderDialog = new CreateFolderDialogPage(page);
 69→    contextMenu = new ContextMenuPage(page);
 70→    confirmDialog = new ConfirmDialogPage(page);
 71→    textEditorDialog = new TextEditorDialogPage(page);
 72→
 73→    // Login using test-login endpoint (bypasses Core Kit, decouples from Web3Auth)
 74→    if (process.env.TEST_LOGIN_SECRET) {
 75→      authState = await loginViaTestEndpoint(page, TEST_CREDENTIALS.email);
 76→    } else {
 77→      await loginViaEmail(page, TEST_CREDENTIALS.email);
 78→      // When using real Core Kit login, extract auth state from Zustand stores
 79→      // for use in bumpServerSequence API calls
 80→      authState = await page.evaluate(() => {
 81→        const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as
 82→          | {
 83→              auth: { getState: () => { accessToken: string } };
 84→              vault: { getState: () => { rootIpnsName: string } };
 85→            }
 86→          | undefined;
 87→
 88→        if (!stores) return null;
 89→
 90→        const authStoreState = stores.auth.getState();
 91→        const vaultStoreState = stores.vault.getState();
 92→
 93→        return {
 94→          accessToken: authStoreState.accessToken,
 95→          rootIpnsName: vaultStoreState.rootIpnsName,
 96→          // Non-sensitive fields only -- private keys stay in browser memory
 97→          email: '',
 98→          publicKeyHex: '',
 99→          publicKeyArr: [],
100→          privateKeyArr: [],
101→          rootFolderKeyArr: [],
102→          rootIpnsPublicKeyArr: [],
103→          rootIpnsPrivateKeyArr: [],
104→          vaultId: '',
105→        } as TestAuthState;
106→      });
107→    }
108→
109→    // Verify we're on the files page and the vault is accessible
110→    await page.waitForURL('**/files', { timeout: 60000 });
111→    await fileList.fileListContainer().waitFor({ state: 'visible', timeout: 30000 });
112→  });
113→
114→  test.afterAll(async () => {
115→    cleanupTestFiles();
116→    if (context) {
117→      await context.close();
118→    }
119→  });
120→
121→  // ============================================================
122→  // Helper: Get current access token from Zustand auth store
123→  // ============================================================
124→
125→  /**
126→   * Get a fresh access token from the browser's Zustand auth store.
127→   * The token may be refreshed between tests.
128→   */
129→  async function getAccessToken(): Promise<string> {
130→    if (authState?.accessToken) {
131→      return authState.accessToken;
132→    }
133→    // Fallback: read from store if authState not available
134→    return await page.evaluate(() => {
135→      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
136→        auth: { getState: () => { accessToken: string } };
137→      };
138→      return stores?.auth?.getState()?.accessToken ?? '';
139→    });
140→  }
141→
142→  /**
143→   * Get the root IPNS name from the browser's Zustand vault store.
144→   */
145→  async function getRootIpnsName(): Promise<string> {
146→    if (authState?.rootIpnsName) {
147→      return authState.rootIpnsName;
148→    }
149→    return await page.evaluate(() => {
150→      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
151→        vault: { getState: () => { rootIpnsName: string } };
152→      };
153→      return stores?.vault?.getState()?.rootIpnsName ?? '';
154→    });
155→  }
156→
157→  // ============================================================
158→  // Test 1: Upload file with stale sequence -> conflict -> retry
159→  // ============================================================
160→
161→  test('upload file to root when sequence is stale -> conflict auto-resolved -> file appears', async () => {
162→    test.slow(); // Allow extra time for conflict re-sync cycle
163→
164→    const fileName = `conflict-upload-${runId}.txt`;
165→
166→    // Step 1: Bump the server-side sequence number so the client's local
167→    // sequence becomes stale. This simulates another device publishing.
168→    const accessToken = await getAccessToken();
169→    const rootIpnsName = await getRootIpnsName();
170→
171→    expect(accessToken).toBeTruthy();
172→    expect(rootIpnsName).toBeTruthy();
173→
174→    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });
175→
176→    // Step 2: Upload a test file via the upload zone.
177→    // The client will:
178→    // - Encrypt the file content and upload to IPFS
179→    // - Build the new folder metadata (with the new file added)
180→    // - Publish the folder IPNS record with its (now-stale) expectedSequenceNumber
181→    // - Receive a 409 Conflict response from the API
182→    // - Re-sync: fetch the latest folder metadata from IPNS
183→    // - Retry the upload with the fresh sequence number
184→    // - Succeed on retry
185→    const testFile = createTestTextFile(fileName, `Conflict detection test file - ${runId}`);
186→    await uploadZone.uploadFile(testFile.path);
187→
188→    // Step 3: Assert the file appears in the file list despite the initial
189→    // conflict. Use a generous timeout to allow for the re-sync cycle.
190→    await fileList.waitForItemToAppear(fileName, { timeout: 60000 });
191→
192→    // Step 4: Assert the operation completed successfully (no persistent error).
193→    // The upload zone should not show an error after conflict auto-resolution.
194→    const hasUploadError = await uploadZone.hasError();
195→    expect(hasUploadError).toBe(false);
196→
197→    // Track for cleanup
198→    createdItems.push({ name: fileName, type: 'file' });
199→  });
200→
201→  // ============================================================
202→  // Test 2: Create folder with stale sequence -> conflict -> retry
203→  // ============================================================
204→
205→  test('create folder when parent sequence is stale -> conflict auto-resolved -> folder appears', async () => {
206→    test.slow(); // Allow extra time for conflict re-sync cycle
207→
208→    const folderName = `conflict-folder-${runId}`;
209→
210→    // Step 1: Bump the server-side sequence number again.
211→    const accessToken = await getAccessToken();
212→    const rootIpnsName = await getRootIpnsName();
213→
214→    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });
215→
216→    // Step 2: Create a folder via the new-folder button.
217→    // The client will hit the same 409 -> re-sync -> retry flow.
218→    const newFolderButton = page.locator('.file-browser-new-folder-button');
219→    await newFolderButton.click();
220→    await createFolderDialog.waitForOpen();
221→    await createFolderDialog.createFolder(folderName);
222→
223→    // Step 3: Assert the folder appears in the file list.
224→    await fileList.waitForItemToAppear(folderName, { timeout: 60000 });
225→
226→    // Step 4: Verify no persistent error state after conflict auto-resolution.
227→    const folderVisible = await fileList.isItemVisible(folderName);
228→    expect(folderVisible).toBe(true);
229→
230→    // Track for cleanup
231→    createdItems.push({ name: folderName, type: 'folder' });
232→  });
233→
234→  // ============================================================
235→  // Test 3 (negative): Per-file IPNS publish does NOT conflict
236→  // ============================================================
237→
238→  test('per-file IPNS content update does not trigger conflict even with stale folder sequence', async () => {
239→    test.slow(); // Allow for file edit + save cycle
240→
241→    // Step 1: Upload a text file to edit later.
242→    // This resets/syncs the root folder sequence as a side effect of the
243→    // successful publish from Test 2.
244→    const editFileName = `conflict-edit-target-${runId}.txt`;
245→    const originalContent = `Original content for conflict edit test - ${runId}`;
246→    const updatedContent = `Updated content via text editor - ${runId} - modified`;
247→
248→    const testFile = createTestTextFile(editFileName, originalContent);
249→    await uploadZone.uploadFile(testFile.path);
250→    await fileList.waitForItemToAppear(editFileName, { timeout: 30000 });
251→
252→    // Step 2: Bump the folder's server-side sequence number.
253→    // This makes the client's local folder sequence stale.
254→    const accessToken = await getAccessToken();
255→    const rootIpnsName = await getRootIpnsName();
256→
257→    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });
258→
259→    // Step 3: Open the text editor for the file and save new content.
260→    // The text editor save flow calls handleUpdateFile, which publishes only
261→    // the per-file IPNS record (NOT the folder IPNS record). Per the Phase 16
262→    // design, per-file IPNS publishes use last-write-wins with no
263→    // expectedSequenceNumber, so they never trigger conflict detection.
264→    await fileList.rightClickItem(editFileName);
265→    await contextMenu.waitForOpen();
266→    await contextMenu.clickEdit();
267→
268→    await textEditorDialog.waitForOpen({ timeout: 15000 });
269→    await textEditorDialog.waitForContentLoaded({ timeout: 15000 });
270→    await textEditorDialog.setContent(updatedContent);
271→    await textEditorDialog.clickSave();
272→    await textEditorDialog.waitForClose({ timeout: 30000 });
273→
274→    // Step 4: Assert the file update completed without a persistent error.
275→    // The file should still be visible in the list (not removed by an error).
276→    await fileList.waitForItemToAppear(editFileName, { timeout: 15000 });
277→    const fileVisible = await fileList.isItemVisible(editFileName);
278→    expect(fileVisible).toBe(true);
279→
280→    // Step 5: Verify no upload-zone error state.
281→    const hasUploadError = await uploadZone.hasError();
282→    expect(hasUploadError).toBe(false);
283→
284→    // Track for cleanup
285→    createdItems.push({ name: editFileName, type: 'file' });
286→  });
287→
288→  // ============================================================
289→  // Cleanup: Remove all items created during conflict tests
290→  // ============================================================
291→
292→  test('cleanup: delete conflict test items', async () => {
293→    // Delete items in reverse creation order (files first, then folders)
294→    const itemsToDelete = [...createdItems].reverse();
295→
296→    for (const item of itemsToDelete) {
297→      const isVisible = await fileList.isItemVisible(item.name).catch(() => false);
298→      if (!isVisible) continue;
299→
300→      await fileList.rightClickItem(item.name);
301→      await contextMenu.waitForOpen();
302→      await contextMenu.clickDelete();
303→      await confirmDialog.waitForOpen();
304→      await confirmDialog.clickConfirm();
305→      await fileList.waitForItemToDisappear(item.name, { timeout: 30000 });
306→    }
307→  });
308→});
309→

