128→/**
129→ * Request an email OTP from the CipherBox backend.
130→ * Returns immediately after the OTP is sent -- the user must check their email.
131→ */
132→export async function requestEmailOtp(email: string): Promise<void> {
133→  const resp = await fetch(`${API_BASE}/auth/identity/email/send-otp`, {
134→    method: 'POST',
135→    headers: { 'Content-Type': 'application/json' },
136→    body: JSON.stringify({ email: email.toLowerCase().trim() }),
137→  });
138→  if (!resp.ok) {
139→    if (resp.status === 429) {
140→      throw new Error('Too many attempts. Please wait before trying again.');
141→    }
142→    throw new Error('Failed to send verification code');
143→  }
144→}
145→
146→/**
147→ * Verify an email OTP and complete login via Core Kit.
148→ *
149→ * Flow:
150→ * 1. Send email + OTP to CipherBox backend -> CipherBox JWT
151→ * 2. Core Kit loginWithJWT with CipherBox JWT
152→ * 3. Export TSS key and pass to Rust backend
153→ */
154→export async function loginWithEmailOtp(email: string, otp: string): Promise<LoginResult> {
155→  if (!coreKit) throw new Error('Core Kit not initialized');
156→
157→  // 1. Verify OTP with CipherBox backend
158→  const resp = await fetch(`${API_BASE}/auth/identity/email/verify-otp`, {
159→    method: 'POST',
160→    headers: { 'Content-Type': 'application/json' },
161→    body: JSON.stringify({ email: email.toLowerCase().trim(), otp }),
162→  });
163→  if (!resp.ok) {
164→    if (resp.status === 401) {
165→      throw new Error('Invalid code. Please check and try again.');
166→    }
167→    throw new Error('OTP verification failed');
168→  }
169→  const { idToken: cipherboxJwt, userId } = await resp.json();
170→
171→  // 2. Core Kit login + key export
172→  return await loginWithCoreKit(cipherboxJwt, userId);
173→}
