604→/**
605→ * Cancel a pending device approval request.
606→ * Cleans up the ephemeral private key from memory.
607→ */
608→export async function cancelApprovalRequest(requestId: string): Promise<void> {
609→  const token = getAccessToken();
610→  if (!token) return;
611→
612→  try {
613→    await fetch(`${API_BASE}/device-approval/${requestId}`, {
614→      method: 'DELETE',
615→      headers: {
616→        Authorization: `Bearer ${token}`,
617→      },
618→    });
619→  } catch {
620→    // Best-effort cleanup -- request may already be expired
621→  }
622→
623→  // Clear ephemeral key
624→  if (ephemeralPrivateKey) {
625→    ephemeralPrivateKey.fill(0);
626→    ephemeralPrivateKey = null;
627→  }
628→}
