683→/**
684→ * Get a Google credential (ID token) via OAuth2 implicit flow in a popup.
685→ *
686→ * GIS One Tap doesn't work in Tauri webview (no Google session, unregistered
687→ * origin). Instead, open a proper Google OAuth consent page in a popup window.
688→ * Tauri's on_new_window handler creates the popup with shared
689→ * WKWebViewConfiguration so window.opener.postMessage works for the callback.
690→ *
691→ * Requires `http://localhost:1420/google-callback.html` to be registered as
692→ * an authorized redirect URI in the Google Cloud Console.
693→ */
694→function getGoogleCredential(): Promise<string> {
695→  return new Promise((resolve, reject) => {
696→    if (!GOOGLE_CLIENT_ID) {
697→      reject(new Error('Google Client ID not configured (VITE_GOOGLE_CLIENT_ID)'));
698→      return;
699→    }
700→
701→    const nonce = crypto.randomUUID();
702→    const state = crypto.randomUUID();
703→    const redirectUri = `${window.location.origin}/google-callback.html`;
704→
705→    const params = new URLSearchParams({
706→      client_id: GOOGLE_CLIENT_ID,
707→      redirect_uri: redirectUri,
708→      response_type: 'id_token',
709→      scope: 'openid email profile',
710→      nonce,
711→      state,
712→      prompt: 'select_account',
713→    });
714→
715→    const authUrl = `https://accounts.google.com/o/oauth2/v2/auth?${params}`;
716→
717→    // Clear any stale result and store expected state for CSRF validation
718→    // Use localStorage (shared across Tauri webviews) instead of sessionStorage (per-window)
719→    localStorage.removeItem('google-auth-result');
720→    localStorage.setItem('google-auth-state', state);
721→
722→    console.log('[Google Auth] Opening OAuth popup...');
723→    // Create the OAuth popup via Tauri IPC command. This bypasses window.open()
724→    // which is unreliable on Windows WebView2 (NewWindowRequested may silently fail).
725→    invoke('open_oauth_popup', { url: authUrl }).catch((err) => {
726→      console.error('[Google Auth] Failed to open popup:', err);
727→      cleanup();
728→      reject(new Error(`Failed to open OAuth popup: ${err}`));
729→    });
730→
731→    const cleanup = () => {
732→      clearInterval(pollStorage);
733→      clearTimeout(timeout);
734→    };
735→
736→    // Poll localStorage for the result (postMessage doesn't survive
737→    // cross-origin redirects in Tauri's WKWebView, and sessionStorage
738→    // is per-window so the popup can't write to the main window's storage)
739→    let pollCount = 0;
740→    const pollStorage = setInterval(() => {
741→      const raw = localStorage.getItem('google-auth-result');
742→      pollCount++;
743→      if (pollCount % 25 === 0) {
744→        console.log(`[Google Auth] Polling... (${pollCount} checks, ${pollCount * 0.2}s)`);
745→      }
746→      if (!raw) return;
747→
748→      localStorage.removeItem('google-auth-result');
749→      cleanup();
750→      console.log('[Google Auth] Got result from callback');
751→
752→      try {
753→        const result = JSON.parse(raw);
754→        if (result.idToken) {
755→          resolve(result.idToken);
756→        } else {
757→          reject(new Error(result.error || 'Google sign-in failed'));
758→        }
759→      } catch {
760→        reject(new Error('Invalid auth callback data'));
761→      }
762→    }, 200);
763→
764→    // Timeout after 2 minutes
765→    const timeout = setTimeout(() => {
766→      cleanup();
767→      console.error('[Google Auth] Timed out after 2 minutes');
768→      reject(new Error('Google authentication timed out'));
769→    }, 120000);
770→  });
771→}
