 38→/**
 39→ * Application initialization sequence.
 40→ */
 41→async function init(): Promise<void> {
 42→  console.log('CipherBox Desktop initializing...');
 43→
 44→  const appDiv = document.getElementById('app');
 45→
 46→  // Show loading state
 47→  if (appDiv) {
 48→    appDiv.innerHTML = loadingHtml('Initializing CipherBox...');
 49→  }
 50→
 51→  // Step 1: Check for dev-key mode (debug builds only — command not
 52→  // registered in release builds, so invoke will reject)
 53→  let devKey: string | null = null;
 54→  try {
 55→    devKey = await invoke('get_dev_key');
 56→  } catch {
 57→    // Expected in release builds where the command isn't registered
 58→  }
 59→  if (devKey) {
 60→    if (appDiv) {
 61→      appDiv.innerHTML = loadingHtml('Dev mode: authenticating with provided key...');
 62→    }
 63→    try {
 64→      await handleDevKeyAuth(devKey);
 65→      handleAuthSuccess(appDiv);
 66→      return;
 67→    } catch (err) {
 68→      const msg = err instanceof Error ? err.message : String(err);
 69→      console.error('Dev-key auth failed:', err);
 70→      // Report to Rust logger so CI can see webview errors
 71→      invoke('log_js_error', { context: 'handleDevKeyAuth', message: msg }).catch(() => {});
 72→      if (appDiv) {
 73→        appDiv.innerHTML = errorHtml(msg || 'Dev-key authentication failed');
 74→      }
 75→      return;
 76→    }
 77→  }
 78→
 79→  // Step 2: Try silent refresh from Keychain
 80→  let silentRefreshOk = false;
 81→  try {
 82→    const refreshed: boolean = await invoke('try_silent_refresh');
 83→    if (refreshed) {
 84→      console.log('API session refreshed from Keychain');
 85→      silentRefreshOk = true;
 86→    }
 87→  } catch (err) {
 88→    console.warn('Silent refresh failed:', err);
 89→    // Not an error -- just means we need full login
 90→  }
 91→
 92→  // Step 3: Initialize Core Kit
 93→  if (appDiv) {
 94→    appDiv.innerHTML = loadingHtml('Connecting to CipherBox...');
 95→  }
 96→
 97→  try {
 98→    await initCoreKit();
 99→  } catch (err) {
100→    console.error('Core Kit initialization failed:', err);
101→    if (appDiv) {
102→      appDiv.innerHTML = errorHtml(
103→        err instanceof Error ? err.message : 'Failed to initialize authentication'
104→      );
105→    }
106→    return;
107→  }
108→
109→  // Step 3b: If Core Kit restored a previous session, try to use it
110→  if (getCoreKitStatus() === 'LOGGED_IN') {
111→    if (silentRefreshOk) {
112→      // Both Core Kit session and API tokens are valid — restore directly
113→      try {
114→        if (appDiv) {
115→          appDiv.innerHTML = loadingHtml('Restoring session...');
116→        }
117→        await restoreSession();
118→        handleAuthSuccess(appDiv);
119→        return;
120→      } catch (err) {
121→        console.warn('Session restore failed, falling back to login:', err);
122→      }
123→    }
124→    // Core Kit has a session but API tokens are stale or restore failed —
125→    // logout Core Kit to get a clean state for fresh login
126→    console.log('Clearing stale Core Kit session before login');
127→    try {
128→      await logout();
129→    } catch {
130→      // Best-effort cleanup
131→    }
132→  }
133→
134→  // Step 4: Show login form
135→  if (appDiv) {
136→    renderLoginForm(appDiv);
137→  }
138→}
