403→  }
404→
405→  // Track active approval request for cleanup
406→  let activeRequestId: string | null = null;
407→  let pollInterval: ReturnType<typeof setInterval> | null = null;
408→
409→  const mfaStatus = document.getElementById('mfa-status')!;
410→
411→  // --- Recovery phrase path ---
412→  document.getElementById('recovery-btn')?.addEventListener('click', () => {
413→    document.getElementById('recovery-form')!.style.display = 'block';
414→    document.getElementById('approval-waiting')!.style.display = 'none';
415→    mfaStatus.textContent = '';
416→    // Cancel any active approval request
417→    if (activeRequestId) {
418→      void cancelApprovalRequest(activeRequestId);
419→      activeRequestId = null;
420→    }
421→    if (pollInterval) {
422→      clearInterval(pollInterval);
423→      pollInterval = null;
424→    }
425→  });
426→
427→  document.getElementById('submit-recovery')?.addEventListener('click', async () => {
428→    const mnemonicEl = document.getElementById('mnemonic-input') as HTMLTextAreaElement;
429→    const mnemonic = mnemonicEl.value.trim();
430→    if (!mnemonic) {
431→      mfaStatus.style.color = '#ef4444';
432→      mfaStatus.textContent = 'Please enter your recovery phrase';
433→      return;
434→    }
435→    // Basic word count validation
436→    const wordCount = mnemonic.split(/\s+/).length;
437→    if (wordCount !== 24) {
438→      mfaStatus.style.color = '#ef4444';
439→      mfaStatus.textContent = `Expected 24 words, got ${wordCount}`;
440→      return;
441→    }
442→    mfaStatus.style.color = '#006644';
443→    mfaStatus.textContent = 'Recovering...';
444→    try {
445→      await inputRecoveryPhrase(mnemonic);
446→      handleAuthSuccess(appDiv);
447→    } catch (err) {
448→      mfaStatus.style.color = '#ef4444';
449→      mfaStatus.textContent = err instanceof Error ? err.message : 'Recovery failed';
450→    }
451→  });
452→
453→  // --- Device approval path ---
454→  document.getElementById('approval-btn')?.addEventListener('click', async () => {
455→    document.getElementById('recovery-form')!.style.display = 'none';
456→    document.getElementById('approval-waiting')!.style.display = 'block';
457→    mfaStatus.textContent = '';
458→
459→    const statusEl = document.getElementById('approval-status')!;
460→
461→    try {
462→      statusEl.style.color = '#006644';
463→      statusEl.textContent = 'Creating approval request...';
464→
465→      activeRequestId = await requestDeviceApproval();
466→      statusEl.textContent = 'Approval request sent. Waiting...';
467→
468→      // Poll every 3 seconds
469→      pollInterval = setInterval(async () => {
470→        if (!activeRequestId) return;
471→        try {
472→          const status = await pollApprovalStatus(activeRequestId);
473→          if (status === 'approved') {
474→            if (pollInterval) clearInterval(pollInterval);
475→            pollInterval = null;
476→            activeRequestId = null;
477→            handleAuthSuccess(appDiv);
478→          } else if (status === 'denied') {
479→            if (pollInterval) clearInterval(pollInterval);
480→            pollInterval = null;
481→            activeRequestId = null;
482→            statusEl.style.color = '#ef4444';
483→            statusEl.textContent = 'Approval was rejected.';
484→          } else if (status === 'expired') {
485→            if (pollInterval) clearInterval(pollInterval);
486→            pollInterval = null;
487→            activeRequestId = null;
488→            statusEl.style.color = '#ef4444';
489→            statusEl.textContent = 'Approval request expired.';
490→          }
491→        } catch {
492→          // Continue polling on transient errors
493→        }
494→      }, 3000);
495→    } catch (err) {
496→      statusEl.style.color = '#ef4444';
497→      statusEl.textContent = 'Failed to request approval';
498→      console.error('[MFA] Approval request error:', err);
499→    }
500→  });
501→
502→  // Cancel approval button
503→  document.getElementById('cancel-approval-btn')?.addEventListener('click', async () => {
504→    if (pollInterval) {
505→      clearInterval(pollInterval);
506→      pollInterval = null;
507→    }
508→    if (activeRequestId) {
509→      await cancelApprovalRequest(activeRequestId);
510→      activeRequestId = null;
511→    }
512→    document.getElementById('approval-waiting')!.style.display = 'none';
513→    mfaStatus.textContent = '';
514→  });
515→
516→  // Back to login button
517→  document.getElementById('mfa-logout-btn')?.addEventListener('click', async () => {
518→    // Clean up any active approval
519→    if (pollInterval) {
520→      clearInterval(pollInterval);
521→      pollInterval = null;
522→    }
523→    if (activeRequestId) {
524→      await cancelApprovalRequest(activeRequestId);
525→      activeRequestId = null;
526→    }
527→    try {
528→      await logout();
529→    } catch (err) {
530→      console.warn('Logout during MFA failed:', err);
531→    }
532→    location.reload();
533→  });
534→}
