560→/**
561→ * Handle dev-key authentication (debug builds only).
562→ *
563→ * Uses the backend's test-login endpoint to get tokens and a deterministic
564→ * keypair, then calls handle_test_login_complete (skips /auth/login POST).
565→ *
566→ * The private key comes from the test-login response (server-generated),
567→ * NOT from the CLI --dev-key argument. This ensures the keypair matches
568→ * the user record so vault ECIES operations succeed.
569→ */
570→async function handleDevKeyAuth(_devKeyHex: string): Promise<void> {
571→  const logStep = (step: string) =>
572→    invoke('log_js_error', { context: 'handleDevKeyAuth', message: `STEP: ${step}` }).catch(
573→      () => {}
574→    );
575→
576→  await logStep('start');
577→
578→  const testLoginSecret = import.meta.env.VITE_TEST_LOGIN_SECRET;
579→  if (!testLoginSecret) {
580→    throw new Error(
581→      'VITE_TEST_LOGIN_SECRET is not set in .env. ' +
582→        "Dev-key mode requires a test-login secret matching the API's TEST_LOGIN_SECRET."
583→    );
584→  }
585→
586→  await logStep(`fetching ${API_BASE}/auth/test-login`);
587→
588→  const resp = await fetch(`${API_BASE}/auth/test-login`, {
589→    method: 'POST',
590→    headers: { 'Content-Type': 'application/json' },
591→    body: JSON.stringify({
592→      email: 'dev-key@cipherbox.local',
593→      secret: testLoginSecret,
594→    }),
595→  });
596→
597→  await logStep(`fetch complete, status=${resp.status}`);
598→
599→  if (!resp.ok) {
600→    const body = await resp.text().catch(() => '');
601→    throw new Error(`Test-login failed (${resp.status}): ${body}`);
602→  }
603→
604→  const data = await resp.json();
605→
606→  await logStep('calling handle_test_login_complete');
607→
608→  // Call handle_test_login_complete with the server-issued tokens and keypair.
609→  // Uses accessToken (not idToken) and privateKeyHex from test-login response
610→  // (not the CLI dev key) so the keypair matches the user record.
611→  await invoke('handle_test_login_complete', {
612→    accessToken: data.accessToken,
613→    refreshToken: data.refreshToken,
614→    privateKeyHex: data.privateKeyHex,
615→    isNewUser: data.isNewUser,
616→  });
617→
618→  await logStep('handle_test_login_complete done');
619→}
